mapper.select:
select department_id, department_code, department_name, department_level, parent_id, manager_id, is_active
from department
where department_id = #{departmentId}

select count(*)
from department
where department_code = #{departmentCode}
  and department_id != #{exceptId}

select count(*)
from department
where department_name = #{departmentName}
  and department_id != #{exceptId}

	and parent_id is null
	and parent_id = #{parentId}

mapper.update:
update department
set manager_id = null
where department_id = #{departmentId}
  and manager_id = #{empId}
